CREATE TYPE "NotificationCategory" AS ENUM ('BOOKING','BOOKING_REMINDER','BOOKING_CHANGE','DEMAND','BEAUTY_JOB','RESULT','PAYMENT','SECURITY','SYSTEM','MARKETING');
CREATE TYPE "ConversationStatus" AS ENUM ('ACTIVE','ARCHIVED');
CREATE TYPE "MessageStatus" AS ENUM ('SENT','DELIVERED','READ');
CREATE TYPE "CommunicationOutboxStatus" AS ENUM ('PENDING','PROCESSED','FAILED');
ALTER TABLE "Notification" ADD COLUMN "category" "NotificationCategory" NOT NULL DEFAULT 'SYSTEM', ADD COLUMN "readAt" TIMESTAMP(3);
ALTER TABLE "NotificationPreference" ADD COLUMN "category" "NotificationCategory" NOT NULL DEFAULT 'SYSTEM';
DROP INDEX "NotificationPreference_scope_channel_key";
CREATE UNIQUE INDEX "NotificationPreference_scope_channel_category_key" ON "NotificationPreference"("businessId","scopeKey","channel","category");
CREATE INDEX "Notification_businessId_userId_readAt_createdAt_idx" ON "Notification"("businessId","userId","readAt","createdAt");
CREATE TABLE "PushDevice" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL,"userId" TEXT NOT NULL,"platform" TEXT NOT NULL,"tokenHash" TEXT NOT NULL,"encryptedToken" TEXT NOT NULL,"isActive" BOOLEAN NOT NULL DEFAULT true,"lastUsedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"invalidatedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("businessId") REFERENCES "Business"("id") ON DELETE CASCADE,FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE);
CREATE UNIQUE INDEX "PushDevice_businessId_tokenHash_key" ON "PushDevice"("businessId","tokenHash"); CREATE INDEX "PushDevice_businessId_userId_isActive_idx" ON "PushDevice"("businessId","userId","isActive");
CREATE TABLE "Conversation" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL,"subject" TEXT,"status" "ConversationStatus" NOT NULL DEFAULT 'ACTIVE',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("businessId") REFERENCES "Business"("id") ON DELETE CASCADE);
CREATE UNIQUE INDEX "Conversation_businessId_id_key" ON "Conversation"("businessId","id"); CREATE INDEX "Conversation_businessId_updatedAt_idx" ON "Conversation"("businessId","updatedAt");
CREATE TABLE "ConversationParticipant" ("businessId" TEXT NOT NULL,"conversationId" TEXT NOT NULL,"userId" TEXT NOT NULL,"joinedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"leftAt" TIMESTAMP(3),PRIMARY KEY("conversationId","userId"),FOREIGN KEY("businessId","conversationId") REFERENCES "Conversation"("businessId","id") ON DELETE CASCADE,FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE);
CREATE INDEX "ConversationParticipant_businessId_userId_leftAt_idx" ON "ConversationParticipant"("businessId","userId","leftAt");
CREATE TABLE "Message" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL,"conversationId" TEXT NOT NULL,"senderUserId" TEXT NOT NULL,"body" TEXT NOT NULL,"status" "MessageStatus" NOT NULL DEFAULT 'SENT',"idempotencyKey" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"editedAt" TIMESTAMP(3),FOREIGN KEY("businessId","conversationId") REFERENCES "Conversation"("businessId","id") ON DELETE CASCADE,FOREIGN KEY("senderUserId") REFERENCES "User"("id") ON DELETE RESTRICT,FOREIGN KEY("businessId") REFERENCES "Business"("id") ON DELETE CASCADE);
CREATE UNIQUE INDEX "Message_businessId_id_key" ON "Message"("businessId","id"); CREATE UNIQUE INDEX "Message_businessId_idempotencyKey_key" ON "Message"("businessId","idempotencyKey"); CREATE INDEX "Message_businessId_conversationId_createdAt_idx" ON "Message"("businessId","conversationId","createdAt");
CREATE TABLE "MessageReceipt" ("messageId" TEXT NOT NULL,"conversationId" TEXT NOT NULL,"userId" TEXT NOT NULL,"deliveredAt" TIMESTAMP(3),"readAt" TIMESTAMP(3),PRIMARY KEY("messageId","userId"),FOREIGN KEY("messageId") REFERENCES "Message"("id") ON DELETE CASCADE,FOREIGN KEY("conversationId","userId") REFERENCES "ConversationParticipant"("conversationId","userId") ON DELETE CASCADE,FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE);
CREATE INDEX "MessageReceipt_userId_readAt_idx" ON "MessageReceipt"("userId","readAt");
CREATE TABLE "CommunicationOutbox" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL,"eventType" TEXT NOT NULL,"aggregateId" TEXT NOT NULL,"idempotencyKey" TEXT NOT NULL,"payload" JSONB NOT NULL,"status" "CommunicationOutboxStatus" NOT NULL DEFAULT 'PENDING',"attempts" INTEGER NOT NULL DEFAULT 0,"availableAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"processedAt" TIMESTAMP(3),"failureReason" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("businessId") REFERENCES "Business"("id") ON DELETE CASCADE);
CREATE UNIQUE INDEX "CommunicationOutbox_businessId_idempotencyKey_key" ON "CommunicationOutbox"("businessId","idempotencyKey"); CREATE INDEX "CommunicationOutbox_status_availableAt_idx" ON "CommunicationOutbox"("status","availableAt"); CREATE INDEX "CommunicationOutbox_businessId_eventType_createdAt_idx" ON "CommunicationOutbox"("businessId","eventType","createdAt");
